151	struct Line { std::u16string t; bool just; };
152	struct Page { std::vector<Line> lines; bool ctx; };
153	
154	static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }
155	
156	static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
157	  std::u16string w;
158	  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
159	  for (char16_t c : s) {
160	    if (c == '\n') { flush(); tok.push_back(u"\n"); }
161	    else if (isWS(c)) flush();
162	    else w.push_back(c);
163	  }
164	  flush();
165	}
166	
167	static std::u16string trim16(const std::u16string& s) {
168	  size_t a = 0, b = s.size();
169	  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
170	  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
171	  return s.substr(a, b - a);
172	}
173	
174	static bool isWriting(const String& cat) {
175	  String c = cat; c.trim(); c.toLowerCase();
176	  return c == "writing" || c == "bài viết" || c == "baiviet";
177	}
178	
179	static std::vector<Page> buildPages(const Quote& q) {
180	  std::vector<Page> pages;
181	  std::u16string content = trim16(u8to16(q.content));
182	  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
183	  std::vector<std::u16string> tok;
184	  tokenize(content, tok);
185	  bool writing = isWriting(q.cat);
186	  size_t ti = 0;
187	  int pageNum = 0;
188	  while (ti < tok.size()) {
189	    pageNum++;
190	    bool first = pageNum == 1;
191	    std::vector<std::u16string> pl;
192	    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
193	      int budget = MAX_CHARS;
194	      if (first && ln == 1) budget = MAX_CHARS - 1;
195	      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
196	      std::u16string cur;
197	      while (ti < tok.size()) {
198	        const std::u16string& nt = tok[ti];
199	        if (nt == u"\n") { ti++; break; }
200	        if (cur.empty()) { cur = nt; ti++; }
201	        else if ((int)(cur.size() + 1 + nt.size()) <= budget) { cur += u" "; cur += nt; ti++; }
202	        else break;
203	      }
204	      pl.push_back(cur);
205	    }
206	    size_t la = ti;
207	    while (la < tok.size() && tok[la] == u"\n") la++;
208	    bool more = la < tok.size();
209	    if (first && !pl.empty()) pl[0] = u"\u201C" + pl[0];
210	    if (more) pl.back() += u"...";
211	    else pl.back() += u"\u201D";
212	    Page pg; pg.ctx = false;
213	    for (size_t i = 0; i < pl.size(); i++) {
214	      bool terminal = !more && i == pl.size() - 1;
215	      bool just = writing && !terminal && pl[i].find(u' ') != std::u16string::npos;
216	      if (!trim16(pl[i]).empty()) pg.lines.push_back({pl[i], just});
217	    }
218	    pages.push_back(pg);
219	  }
220	  // context pages
221	  if (q.context.length() > 0) {
222	    std::vector<std::u16string> cw;
223	    tokenize(u8to16(q.context), cw);
224	    size_t ci = 0;
225	    bool firstCtx = true;
226	    while (ci < cw.size()) {
227	      std::vector<std::u16string> cl;
228	      for (int l = 1; l <= MAX_LINES && ci < cw.size(); l++) {
229	        int budget = (l == MAX_LINES) ? MAX_CHARS - 4 : MAX_CHARS;
230	        std::u16string cur;
231	        if (firstCtx && l == 1) { cur = u"[Note] "; firstCtx = false; }
232	        while (ci < cw.size()) {
233	          if (cw[ci] == u"\n") { ci++; continue; }
234	          if (cur.empty()) { cur = cw[ci]; ci++; }
235	          else if ((int)(cur.size() + 1 + cw[ci].size()) <= budget || cur == u"[Note] ") {
236	            if (cur != u"[Note] ") cur += u" ";
237	            cur += cw[ci]; ci++;
238	          } else break;
239	        }
240	        cl.push_back(cur);
241	      }
242	      if (ci < cw.size() && !cl.empty()) cl.back() += u"...";
243	      Page pg; pg.ctx = true;
244	      for (auto& s : cl) {
245	        if (!trim16(s).empty()) pg.lines.push_back({s, false});
246	      }
247	      if (!pg.lines.empty()) pages.push_back(pg);
248	    }
249	  }
250	  return pages;
251	}
