264	// ------------------------------------------------------------------ drawing helpers
265	static uint16_t hsl565(float h, float s, float l) {
266	  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
267	  float c = (1 - fabsf(2 * l - 1)) * s;
268	  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
269	  float m = l - c / 2, r = 0, g = 0, b = 0;
270	  if (h < 60) { r = c; g = x; }
271	  else if (h < 120) { r = x; g = c; }
272	  else if (h < 180) { g = c; b = x; }
273	  else if (h < 240) { g = x; b = c; }
274	  else if (h < 300) { r = x; b = c; }
