5	// Minimal reader + software renderer for the VLW-layout fonts from tools/make_fonts.py
6	struct Glyph {
7	  int w, h, adv, dY, dX;
8	  const uint8_t* bits;
9	};
10	
11	struct VFont {
12	  const uint8_t* d = nullptr;
13	  uint32_t n = 0;
14	  int size = 0, ascent = 0, descent = 0, adv = 0;
15	  const uint8_t* recs = nullptr;
16	  const uint8_t* bmp = nullptr;
17	
18	  static int32_t be(const uint8_t* p) {
19	    return (int32_t)(((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3]);
20	  }
21	  void init(const uint8_t* data) {
22	    d = data;
23	    n = be(d);
24	    size = be(d + 8);
25	    ascent = be(d + 16);
26	    descent = be(d + 20);
27	    recs = d + 24;
28	    bmp = recs + n * 28;
29	    Glyph g;
30	    adv = find('M', g) ? g.adv : size * 6 / 10;
31	  }
32	  bool find(char16_t cp, Glyph& g) const {
33	    int lo = 0, hi = (int)n - 1;
34	    while (lo <= hi) {
35	      int mid = (lo + hi) >> 1;
36	      const uint8_t* r = recs + mid * 28;
37	      int32_t u = be(r);
38	      if (u == cp) {
39	        g.h = be(r + 4);
40	        g.w = be(r + 8);
41	        g.adv = be(r + 12);
42	        g.dY = be(r + 16);
43	        g.dX = be(r + 20);
44	        g.bits = bmp + be(r + 24);
45	        return true;
46	      } else if (u < cp) lo = mid + 1;
47	      else hi = mid - 1;
48	    }
49	    return false;
50	  }
51	};
52	
53	static inline uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
54	  return ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3);
55	}
56	
57	static inline uint16_t mix565(uint16_t d, uint16_t s, uint8_t a) {
58	  uint32_t dr = d >> 11, dg = (d >> 5) & 63, db = d & 31;
59	  uint32_t sr = s >> 11, sg = (s >> 5) & 63, sb = s & 31;
60	  uint32_t ia = 255 - a;
61	  uint32_t r = (dr * ia + sr * a) / 255;
62	  uint32_t g = (dg * ia + sg * a) / 255;
63	  uint32_t b = (db * ia + sb * a) / 255;
64	  return (r << 11) | (g << 5) | b;
65	}
66	
67	extern int g_missingGlyphs;
68	
69	// Off-screen RGB565 canvas that renders glyphs with alpha blending
70	struct Canvas {
71	  uint16_t* b;
72	  int w, h;
73	  void fill(uint16_t c) {
74	    for (int i = 0; i < w * h; i++) b[i] = c;
75	  }
76	  void rect(int x, int y, int rw, int rh, uint16_t c) {
77	    for (int j = y; j < y + rh; j++) {
78	      if (j < 0 || j >= h) continue;
79	      for (int i = x; i < x + rw; i++)
80	        if (i >= 0 && i < w) b[j * w + i] = c;
81	    }
82	  }
83	  int drawChar(const VFont& f, int x, int base, char16_t ch, uint16_t col) {
84	    Glyph g;
85	    if (!f.find(ch, g)) {
86	      g_missingGlyphs++;
87	      if (!f.find('?', g)) return f.adv;
88	    }
89	    int gx0 = x + g.dX, gy0 = base - g.dY;
90	    for (int gy = 0; gy < g.h; gy++) {
91	      int py = gy0 + gy;
92	      if (py < 0 || py >= h) continue;
93	      for (int gx = 0; gx < g.w; gx++) {
94	        int px = gx0 + gx;
95	        if (px < 0 || px >= w) continue;
96	        uint8_t a = g.bits[gy * g.w + gx];
97	        if (a < 64) continue; // Cut out faint blurry grey fog around letters
98	        uint16_t* dst = &b[py * w + px];
99	        if (a >= 140) {
100	          *dst = col; // Solid, razor-sharp stroke
101	        } else {
102	          // Gamma boost edge pixels so they don't blend into dark mud
103	          uint8_t boosted = (uint8_t)(a + (255 - a) * 3 / 4);
104	          *dst = mix565(*dst, col, boosted);
105	        }
106	      }
107	    }
108	    return g.adv;
109	  }
110	  int text(const VFont& f, int x, int base, const std::u16string& s, uint16_t col, int maxW = 100000) {
111	    int x0 = x;
112	    for (char16_t c : s) {
113	      if (x - x0 + f.adv > maxW) break;
114	      x += drawChar(f, x, base, c, col);
115	    }
116	    return x - x0;
117	  }
118	};
