struct Btn {
  uint8_t pin; bool last = true; uint32_t t = 0;
  bool pressed() {
    bool v = digitalRead(pin);
    uint32_t now = millis();
    bool fire = (last && !v && now - t > 40);
    if (v != last) t = now;
    last = v;
    return fire;
  }
};
static Btn btnRoll = {PIN_BTN_ROLL}, btnScroll = {PIN_BTN_SCROLL};
static uint32_t lastRefresh = 0;

void setup() {
  Serial.begin(115200);
  Serial1.begin(9600, SERIAL_8N1, -1, PIN_JQ_TX);
  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
  randomSeed(esp_random());

  // Reset display with RST pin toggling
  pinMode(PIN_LCD_RST, OUTPUT);
  digitalWrite(PIN_LCD_RST, LOW);
  delay(100);
  digitalWrite(PIN_LCD_RST, HIGH);
  delay(100);

  tft.init();
  tft.setRotation(1);
  tft.setBrightness(255);
  tft.fillScreen(C_BLACK);

  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
  Serial.println("Fonts initialized");

  delay(600);
  Serial.println("Setting JQ8900 volume...");
  jqVolume(JQ_VOLUME);
  Serial.printf("JQ8900 volume set to %d\n", JQ_VOLUME);

  Serial.println("Showing splash screen...");
  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
  delay(900);

  loadFallbackQuotes();
  if (strlen(WIFI_SSID) > 0) {
    splash("Connecting Wi-Fi...", WIFI_SSID);
    WiFi.mode(WIFI_STA);
    WiFi.setTxPower(WIFI_POWER_8_5dBm);
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    uint32_t t0 = millis();
    while (WiFi.status() != WL_CONNECTED && millis() - t0 < 15000) delay(200);
    if (WiFi.status() == WL_CONNECTED) {
      Serial.printf("[wifi] %s\n", WiFi.localIP().toString().c_str());
      splash("Syncing prescripts...", "");
      if (!fetchQuotes()) { splash("Sync failed", "using offline cache"); delay(1200); }
    } else {
      splash("Wi-Fi unavailable", "using offline cache");
      delay(1200);
    }
  } else {
    Serial.println("[wifi] no SSID configured -> offline cache");
  }
  lastRefresh = millis();
  int start = 0;
  for (size_t i = 0; i < quotes.size(); i++) if (quotes[i].idx == "6") start = i;
  loadQuote(start, true, true);
}

void loop() {
  if (animating) stepAnimation();
  if (btnRoll.pressed()) { Serial.println("[btn] ROLL"); rollQuote(); }
  if (btnScroll.pressed()) { Serial.println("[btn] SCROLL"); changePage(); }

  if (!animating && autoPageAt && millis() >= autoPageAt) {
