// Schedule complete_sound.wav chimes to fill the gap until text resolves
function startGapChimeScheduler() {
  stopGapChimeScheduler();
  if (!soundEnabled || !userHasInteracted) return;

  // 1. Initial delay of 1250ms between draw_sound.wav and the first complete_sound chime
  gapChimeTimer = setTimeout(function chimeLoop() {
    if (!isDrawing) return;
    playSoundEffect('complete');

    // 2. Subsequent 150ms delay between complete_sound chimes to fill the gap
    gapChimeTimer = setTimeout(chimeLoop, DELAY_BETWEEN_COMPLETES_MS);
  }, DELAY_DRAW_TO_COMPLETE_MS);
}

// Auto-Page Engine (Always ON): 7s * number of lines of content
function resetAutoPageTimer(activePage) {
  if (autoPageTimer) {
    clearTimeout(autoPageTimer);
    autoPageTimer = null;
  }
  if (!activePage || !activePage.lines) return;

  const lineCount = activePage.lines.filter(l => !l.isBlank && l.text && l.text.trim()).length || 1;
  const dwellMs = lineCount * 7000; // 7s * number of lines of content

  const statusEl = document.getElementById('auto-page-status');
  if (statusEl) {
    statusEl.textContent = `Auto: ${lineCount * 7}s (${lineCount}L)`;
  }

  autoPageTimer = setTimeout(() => {
    if (currentPage < totalPages) {
      changePage(1);
    } else {
      navQuote(1); // loop to next prescript
    }
  }, dwellMs);
}

// ==============================================================================
// PRESCRIPT CHAOS ➔ ENTROPY ➔ CONTENT TRANSFORMATION ENGINE
// ==============================================================================
const SCRAMBLE_CHARS = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789!$*+=-~?/";
const NUM_SCRAMBLE_CHARS = SCRAMBLE_CHARS.length;

function getRandomCipherChar() {
  return SCRAMBLE_CHARS[Math.floor(Math.random() * NUM_SCRAMBLE_CHARS)];
}


let isDrawing = false;
let typingTimer = null;
let lastRenderedPageData = null;
let lastRenderedAlignClass = 'content-left';
let lastFinalHeaderTitleHTML = '';

function stopDrawingAnimation() {
  if (typingTimer) {
    cancelAnimationFrame(typingTimer);
    clearTimeout(typingTimer);
    typingTimer = null;
  }
  isDrawing = false;
  const led = document.querySelector('.beeper-led');
  if (led) led.classList.remove('drawing');
}

function mapLinesToFourRows(lines) {
  // Return active lines dynamically without artificial 4-row padding
  return (lines || []).filter(l => l && (l.text ? l.text.trim().length > 0 : String(l).trim().length > 0));
}

function parseDecoratedLine(lineItem) {
  const isBlank = (lineItem && lineItem.isBlank) || false;
  const rawHtml = (typeof lineItem === 'object' && lineItem !== null) ? lineItem.html : lineItem;
  const align = (typeof lineItem === 'object' && lineItem !== null) ? (lineItem.align || 'line-left') : 'line-left';
  let prefix = '';
  let suffix = '';
  let text = rawHtml || '';

  if (isBlank) {
    return { prefix: '', text: '', suffix: '', align: 'line-left', isBlank: true };
  }

  const openTag = text.match(/^(<span class="ep-qmark ep-qmark-open"[^>]*>“<\/span>)/);
  if (openTag) {
    prefix = openTag[1];
    text = text.substring(openTag[0].length);
  }

  const closeTag = text.match(/(<span class="ep-qmark ep-qmark-close"[^>]*>”<\/span>|<span class="ep-ellipsis-cue"[^>]*>\.\.\.<\/span>)$/);
  if (closeTag) {
    suffix = closeTag[1];
    text = text.substring(0, text.length - closeTag[0].length);
  }

  return { prefix, text, suffix, align, isBlank: false };
}

