static void splash(const char* l1, const char* l2 = "") {
  cv.h = 24;
  tft.fillRect(0, 60, SW, 60, C_BLACK);
  std::u16string a = u8to16(l1), b = u8to16(l2);
  cv.fill(C_BLACK);
  cv.text(fSB10, (SW - (int)a.size() * fSB10.adv) / 2, 16, a, C_WHITE);
  push(66, 24);
  cv.fill(C_BLACK);
  cv.text(fRG10, (SW - (int)b.size() * fRG10.adv) / 2, 16, b, C_GHOST);
  push(92, 24);
}

struct Btn {
  uint8_t pin;
  bool lastState = true;
  uint32_t lastPressTime = 0;

  bool pressed() {
    bool reading = digitalRead(pin);
    uint32_t now = millis();
    bool fired = false;

    // Detect falling edge: transition from HIGH (released) to LOW (pressed)
    if (lastState && !reading) {
      if (lastPressTime == 0 || now - lastPressTime > 150) {
        lastPressTime = now;
        fired = true;
      }
    }
    lastState = reading; // Always track actual state, cannot lock out
    return fired;
  }
};
static Btn btnRoll = {PIN_BTN_ROLL};
static Btn btnRollAlt = {PIN_BTN_ROLL_ALT};
static Btn btnBoot = {PIN_BTN_BOOT};
static Btn btnScroll = {PIN_BTN_SCROLL};
static Btn btnScrollAlt = {PIN_BTN_SCROLL_ALT};

void setup() {
  Serial.begin(115200);
  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_ROLL_ALT, INPUT_PULLUP);
  pinMode(PIN_BTN_BOOT, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
  pinMode(PIN_BTN_SCROLL_ALT, INPUT_PULLUP);
  randomSeed(esp_random());

  // Initialize audio driver
  audio.begin(PIN_JQ_TX);
  delay(100);
  audio.setVolume(JQ_VOLUME);

  // Hardware reset pulse on LCD RST pin
  pinMode(PIN_LCD_RST, OUTPUT);
  digitalWrite(PIN_LCD_RST, HIGH);
  delay(50);
  digitalWrite(PIN_LCD_RST, LOW);
  delay(100);
  digitalWrite(PIN_LCD_RST, HIGH);
  delay(150);

  tft.init();
  tft.setRotation(1);
  tft.setBrightness(255);
  tft.fillScreen(C_BLACK);

  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
  Serial.println("Fonts initialized");

  delay(300);

  Serial.println("Showing splash screen...");
  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
  delay(900);

  loadFallbackQuotes();
  if (strlen(WIFI_SSID) > 0) {
    splash("Connecting Wi-Fi...", WIFI_SSID);
    WiFi.mode(WIFI_STA);
    WiFi.setTxPower(WIFI_POWER_8_5dBm);
    WiFi.begin(WIFI_SSID, WIFI_PASS);
    uint32_t t0 = millis();
    while (WiFi.status() != WL_CONNECTED && millis() - t0 < 15000) delay(200);
    if (WiFi.status() == WL_CONNECTED) {
      Serial.printf("[wifi] %s\n", WiFi.localIP().toString().c_str());
      splash("Syncing prescripts...", "");
      if (!fetchQuotes()) { splash("Sync failed", "using offline cache"); delay(1200); }
    } else {
      splash("Wi-Fi unavailable", "using offline cache");
      delay(1200);
    }
  } else {
    Serial.println("[wifi] no SSID configured -> offline cache");
  }

  int start = 0;
  for (size_t i = 0; i < quotes.size(); i++) if (quotes[i].idx == "6") start = i;
  loadQuote(start, true, true);
}

void loop() {
  // Serial command interface for remote manual triggering
  if (Serial.available()) {
    char ch = Serial.read();
    if (ch == 'r' || ch == 'R') {
      Serial.println("[SIM] ROLL trigger");
      rollQuote();
      return;
    }
    if (ch == 's' || ch == 'S' || ch == 'p' || ch == 'P') {
      Serial.println("[SIM] SCROLL / PAGE trigger");
      changePage();
      return;
    }
  }

  // Physical button checks (100% manual control)
  if (btnRoll.pressed() || btnRollAlt.pressed() || btnBoot.pressed()) {
    Serial.println("[btn] ROLL");
    rollQuote();
    return;
  }
  if (btnScroll.pressed() || btnScrollAlt.pressed()) {
    Serial.println("[btn] SCROLL");
    changePage();
    return;
  }

