struct Btn {
  uint8_t pin;
  bool latched = false;
  uint32_t highSince = 0;

  bool pressed() {
    bool reading = digitalRead(pin);
    uint32_t now = millis();

    if (reading == LOW) {
      highSince = 0;
      if (!latched) {
        latched = true;
        return true; // 0ms instantaneous response on press
      }
    } else {
      if (latched) {
        if (highSince == 0) {
          highSince = now;
        } else if (now - highSince >= 40) {
          // Stably released for 40ms, release latch
          latched = false;
          highSince = 0;
        }
      }
    }
    return false;
  }
};
static Btn btnRoll = {PIN_BTN_ROLL};
static Btn btnRollLegacy = {PIN_BTN_ROLL_LEGACY};
static Btn btnScroll = {PIN_BTN_SCROLL};
static Btn btnScrollLegacy = {PIN_BTN_SCROLL_LEGACY};

void setup() {
  // Disable hardware brownout detector to prevent nuisance resets during speaker amplifier transients
  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0);

  Serial.begin(115200);
