597	struct Btn {
598	  uint8_t pin;
599	  bool latched = false;
600	  uint32_t highSince = 0;
601	
602	  bool pressed() {
603	    bool reading = digitalRead(pin);
604	    uint32_t now = millis();
605	
606	    if (reading == LOW) {
607	      highSince = 0;
608	      if (!latched) {
609	        latched = true;
610	        return true; // 0ms instantaneous response on press
611	      }
612	    } else {
613	      if (latched) {
614	        if (highSince == 0) {
615	          highSince = now;
616	        } else if (now - highSince >= 40) {
617	          // Stably released for 40ms, release latch
618	          latched = false;
619	          highSince = 0;
620	        }
621	      }
622	    }
623	    return false;
624	  }
625	};
