struct Btn {
  uint8_t pin;
  bool latched = false;
  uint32_t highSince = 0;

  bool pressed() {
    bool reading = digitalRead(pin);
    uint32_t now = millis();

    if (reading == LOW) {
      highSince = 0;
      if (!latched) {
        latched = true;
        return true; // 0ms instantaneous response on press
      }
    } else {
      if (latched) {
        if (highSince == 0) {
          highSince = now;
        } else if (now - highSince >= 40) {
          // Stably released for 40ms, release latch
          latched = false;
          highSince = 0;
        }
      }
    }
    return false;
  }
};
