}

void loop() {
  // Serial command interface for remote manual triggering
  if (Serial.available()) {
    char ch = Serial.read();
    if (ch == 'r' || ch == 'R') {
      Serial.println("[SIM] ROLL trigger");
      rollQuote();
      return;
    }
    if (ch == 's' || ch == 'S' || ch == 'p' || ch == 'P') {
      Serial.println("[SIM] SCROLL / PAGE trigger");
      changePage();
      return;
    }
  }

  // Physical button checks (100% manual control, dedicated clean pins)
  if (btnRoll.pressed() || btnRollLegacy.pressed()) {
    Serial.println("[btn] ROLL");
    rollQuote();
    return;
  }
  if (btnScroll.pressed() || btnScrollLegacy.pressed()) {
    Serial.println("[btn] SCROLL");
    changePage();
    return;
  }

  if (animating) {
    stepAnimation();
  }

  // Pure manual mode: NO auto-page, NO auto-reroll!
  delay(1);
}

