  q.context = "Network Standby";
  q.date = "Live Cloud";
  q.specific = "Offline Standby";
  q.container = "Cloudflare Edge";
  q.cat = "system";
  q.tags = {"#Offline", "#Cloudflare"};
  quotes.push_back(q);
